insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('682e6bd2-c75d-4cce-ab67-8528a789b2dc', 'B-Stance Romanian Deadlift', ARRAY['Stagger your stance: front foot flat, back foot on the toes.', 'Most of your weight on the front leg.', 'Hold the kettlebell and hinge at the hips.', 'Keep a long spine.', 'Drive the hips forward to stand.', 'Finish the set, then switch the stance.']::text[], '{}', true)
insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('0f82338a-fdb6-4218-aad0-98e7009b8447', 'Floor Press', ARRAY['Lie on your back with the kettlebell in one hand.', 'Upper arm on the floor, elbow about 45 degrees from your body.', 'Press until the arm is straight.', 'Lower until the upper arm meets the floor.', 'Finish the set, then switch sides.']::text[], '{}', true)
insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('b2b7cc82-a241-4edc-a0cd-c20b3052f314', 'Single-Leg Romanian Deadlift', ARRAY['Hold the kettlebell in one or both hands.', 'Stand on one leg with a soft knee.', 'Hinge at the hips and send the free leg back.', 'Keep a long spine.', 'Feel the hamstring and glute on the standing leg.', 'Drive the hips forward to stand.']::text[], '{}', true)
insert into public.glossary_entries (id, name, steps, notes, is_builtin) values ('93a7b7d3-328a-494a-a35b-32c0d63e51db', 'Suitcase Carry', ARRAY['Stand tall holding the kettlebell by your side.', 'Walk slowly with a braced core.', 'Keep shoulders and hips level.', 'Switch hands halfway through the set.']::text[], '{}', true)
insert into public.programs (id, user_id, title, stage, duration, difficulty, focus, equipment, warmup, phases, is_builtin, is_public, sort) values ('a0dc9b80-9101-4997-afb3-2a19778df3ee', null, 'Muscle-focused kettlebell program', 'Muscle', null, 'Intermediate', 'Build and retain muscle while losing fat.', ARRAY['1 × 12 kg kettlebell', '1 × 16 kg kettlebell', '1 × 20 kg kettlebell']::text[], '{"label":"Repeat for 5 minutes","totalSec":300,"steps":[{"name":"March or jog on the spot","durationSec":30},{"name":"Slow bodyweight squats","durationSec":15},{"name":"Arm circles","durationSec":15}]}'::jsonb, '[{"month":1,"name":"Muscle","focus":"Build and retain muscle while losing fat."}]'::jsonb, true, true, 1);
